#pragma once
#include "vulkan_graphics_pipeline_candidate.h"
struct VkProbeViewInfo{uint32_t type;const void*next;uint32_t flags;uint64_t image;uint32_t viewType,format,components[4],aspect,baseMip,mips,baseLayer,layers;};
struct VkProbeSamplerInfo{uint32_t type;const void*next;uint32_t flags,mag,min,mipmap,u,v,w;float bias;uint32_t anisotropy;float maxAnisotropy;uint32_t compare,compareOp;float minLod,maxLod;uint32_t border,unnormalized;};
struct VkProbeLayoutBinding{uint32_t binding,type,count,stages;const uint64_t*immutable;};
struct VkProbeLayoutInfo{uint32_t type;const void*next;uint32_t flags,count;const VkProbeLayoutBinding*bindings;};
struct VkProbePoolSize{uint32_t type,count;};
struct VkProbeDescriptorPoolInfo{uint32_t type;const void*next;uint32_t flags,maxSets,count;const VkProbePoolSize*sizes;};
struct VkProbeDescriptorAllocation{uint32_t type;const void*next;uint64_t pool;uint32_t count;const uint64_t*layouts;};
struct VkProbeDescriptorImage{uint64_t sampler,view;uint32_t layout;};
struct VkProbeDescriptorWrite{uint32_t type;const void*next;uint64_t set;uint32_t binding,element,count,descriptorType;const VkProbeDescriptorImage*images;const void*buffers;const uint64_t*views;};
using VkProbeCreateView=int32_t(WINAPI*)(Handle,const VkProbeViewInfo*,const void*,uint64_t*);
using VkProbeCreateSampler=int32_t(WINAPI*)(Handle,const VkProbeSamplerInfo*,const void*,uint64_t*);
using VkProbeCreateLayout=int32_t(WINAPI*)(Handle,const VkProbeLayoutInfo*,const void*,uint64_t*);
using VkProbeCreateDescriptorPool=int32_t(WINAPI*)(Handle,const VkProbeDescriptorPoolInfo*,const void*,uint64_t*);
using VkProbeAllocateDescriptors=int32_t(WINAPI*)(Handle,const VkProbeDescriptorAllocation*,uint64_t*);
using VkProbeUpdateDescriptors=void(WINAPI*)(Handle,uint32_t,const VkProbeDescriptorWrite*,uint32_t,const void*);
inline void testVulkanTextureBindingCandidate(HMODULE library,Handle device,uint64_t image,Handle physical,Handle queue,uint32_t family,const std::string&base){
 static_assert(sizeof(VkProbeViewInfo)==80&&sizeof(VkProbeSamplerInfo)==80&&sizeof(VkProbeLayoutInfo)==32&&sizeof(VkProbeDescriptorPoolInfo)==40&&sizeof(VkProbeDescriptorAllocation)==40&&sizeof(VkProbeDescriptorWrite)==64,"Vulkan descriptor ABI");
 auto createView=load<VkProbeCreateView>(library,"vkCreateImageView");auto destroyView=load<VkProbeDestroyBuffer>(library,"vkDestroyImageView");auto createSampler=load<VkProbeCreateSampler>(library,"vkCreateSampler");auto destroySampler=load<VkProbeDestroyBuffer>(library,"vkDestroySampler");auto createLayout=load<VkProbeCreateLayout>(library,"vkCreateDescriptorSetLayout");auto destroyLayout=load<VkProbeDestroyBuffer>(library,"vkDestroyDescriptorSetLayout");auto createPool=load<VkProbeCreateDescriptorPool>(library,"vkCreateDescriptorPool");auto destroyPool=load<VkProbeDestroyBuffer>(library,"vkDestroyDescriptorPool");auto allocate=load<VkProbeAllocateDescriptors>(library,"vkAllocateDescriptorSets");auto update=load<VkProbeUpdateDescriptors>(library,"vkUpdateDescriptorSets");uint64_t view=0,sampler=0,layout=0,pool=0;auto cleanup=[&](){if(pool)destroyPool(device,pool,nullptr);if(layout)destroyLayout(device,layout,nullptr);if(sampler)destroySampler(device,sampler,nullptr);if(view)destroyView(device,view,nullptr);};auto check=[](int32_t result){if(result)throw std::runtime_error("Vulkan binding result "+std::to_string(result));};
 try{VkProbeViewInfo viewInfo{};viewInfo.type=15;viewInfo.image=image;viewInfo.viewType=1;viewInfo.format=37;viewInfo.aspect=viewInfo.mips=viewInfo.layers=1;check(createView(device,&viewInfo,nullptr,&view));VkProbeSamplerInfo samplerInfo{};samplerInfo.type=31;samplerInfo.mag=samplerInfo.min=samplerInfo.mipmap=1;samplerInfo.u=samplerInfo.v=samplerInfo.w=2;samplerInfo.maxAnisotropy=1;check(createSampler(device,&samplerInfo,nullptr,&sampler));VkProbeLayoutBinding bindings[4]{{0,2,1,0x10,nullptr},{1,0,1,0x10,nullptr},{2,2,1,0x10,nullptr},{3,2,1,0x10,nullptr}};VkProbeLayoutInfo layoutInfo{};layoutInfo.type=32;layoutInfo.count=4;layoutInfo.bindings=bindings;check(createLayout(device,&layoutInfo,nullptr,&layout));VkProbePoolSize sizes[2]{{2,3},{0,1}};VkProbeDescriptorPoolInfo poolInfo{};poolInfo.type=33;poolInfo.maxSets=1;poolInfo.count=2;poolInfo.sizes=sizes;check(createPool(device,&poolInfo,nullptr,&pool));VkProbeDescriptorAllocation allocation{};allocation.type=34;allocation.pool=pool;allocation.count=1;allocation.layouts=&layout;uint64_t set=0;check(allocate(device,&allocation,&set));VkProbeDescriptorImage images[4]{{0,view,5},{sampler,0,0},{0,view,5},{0,view,5}};VkProbeDescriptorWrite writes[4]{};for(uint32_t n=0;n<4;++n){writes[n].type=35;writes[n].set=set;writes[n].binding=n;writes[n].count=1;writes[n].descriptorType=n==1?0:2;writes[n].images=&images[n];}update(device,4,writes,0,nullptr);std::cout<<"Vulkan sampled-image/sampler descriptor setup passed bindings=4\n";testVulkanGraphicsPipelineCandidate(library,device,layout,set,physical,queue,family,base);cleanup();}catch(...){cleanup();throw;}
}
